          "detailMarkdown": "## 6914 阜爾運通 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2025 年營收為 **56.78 億元**，較 2024 年 **47.17 億元**成長；2026 年 Q1 營收 **14.36 億元**，年增 **9.24%**。\n- 2026 年 Q1 稅後淨利 **1.55 億元**，EPS **2.34 元**；毛利率 **21.98%**，與去年同期相近。\n- 2025 年全年稅後淨利 **6.36 億元**，EPS **9.60 元**；近 5 年營收與獲利均呈成長趨勢。\n- 2026 年 Q1 產品別營收以**停車場收費及管理服務**為主，簡報顯示占比約 **92%**。\n- 管理層於 Q&A 提到，手上現金約 **13–14 億元**，可用銀行額度約 **5–6 億元**；財務成本增加主要與**使用權資產/租賃負債**相關，而非實際借款大增。\n\n### 展望與成長利基\n- 系統銷售端持續推新一代智能停管系統，強調模組化、遠端管理與降低維運成本。\n- 路邊停車業務持續擴張，簡報提及台東市專案，預計建置逾 **1,000 格**智慧開單系統，整體管理規模已突破 **24,000 格**。\n- 停車場經營端目標為 **2026 年朝 1,450 場以上**邁進，並持續拓展家樂福、好市多等大型場域。\n- 海外方面，泰國已營運 **4 個案場**，並規劃設立在地分公司；日本市場亦已啟動布局，首波聚焦關東地區。\n- 管理層多次提到 BOT、大型投資案與策略性收購評估，以延長經營年限並提升長期收益穩定性。\n\n### 產品、客戶與市場位置\n- 管理層表示，台灣市場維持審慎樂觀，並以擴大案場數、提升系統整合能力、拓展大型場域與海外市場為主軸。\n- 會中也多次提及：大型量販/購物中心、路邊停車、智慧醫療、訪客系統、海外泰國與日本布局。\n- 2026 年 Q1 產品別營收以**停車場收費及管理服務**為主，簡報顯示占比約 **92%**。\n- 海外方面，泰國已營運 **4 個案場**，並規劃設立在地分公司；日本市場亦已啟動布局，首波聚焦關東地區。\n\n### 風險與不確定性\n- 簡報載明前瞻性資訊可能受風險、不確定性及推論影響，實際結果可能與預期不同。\n- 海外拓點與投資案涉及當地法規、資金投入、合作進度與營運整合，具執行不確定性。\n- 停車場案場續約、標案取得及大型商場經營權移轉，存在競爭與合約變動風險。\n- 公司提到部分大型案場到期未續約，顯示營收仍可能受單一案場異動影響。\n- Q&A 中亦提及路邊停車毛利會因地區與案場量能差異而變動，獲利穩定度可能受專案結構影響。\n- **需人工確認**：簡報第 5 頁股東結構百分比與語音轉錄未逐一對應，僅見總資本額與員工數；未提供完整股東明細。\n- **需人工確認**：語音提到「2024 年 5 月 3 日掛牌」，但公司簡報未在此頁明示掛牌日期，建議與公開資訊再核對。\n- **需人工確認**：簡報第 21 頁顯示 2026 年 Q1 經營場次 **1,382 場**，語音中曾提到「3 月已經大概到 1382 左右、4 月應已突破 1400 場」，後者為口頭推估。\n\n### Q&A 與管理層口氣\n- 泰國業務：目前有 **4 個停車場**，包含物業管理與平面停車場，管理層表示目前多數案場皆有獲利，毛利率約與台灣相近。\n- 路邊停車毛利：管理層回覆約落在 **23%–28%**，因台中、台東、竹北等專案規模不同而有所差異。\n- 現金股利：管理層表示將延續高現金股利政策，會議中口頭提及**至少 6 元現金股利**，但與簡報中的歷年配發資訊需再核對。\n- 2026 年營收成長：管理層口頭表示，儘管前 4 月營收表現較往年保守，仍認為全年有機會維持**雙位數成長**。\n- 日本布局：管理層提到下半年可能設立日本停車公司，並已有大型場域合作進展，但尚待公告與落地。\n\n### 評分利基點\n- 加分主因：管理層表示，台灣市場維持審慎樂觀，並以擴大案場數、提升系統整合能力、拓展大型場域與海外市場為主軸。；今年營運目標提及希望營收維持**雙位數成長**，並朝**60 億元**規模邁進。；2025 年營收為 **56.78 億元**，較 2024 年 **47.17 億元**成長；2026 年 Q1 營收 **14.36 億元**，年增 **9.24%**。。\n- 扣分或保留：簡報載明前瞻性資訊可能受風險、不確定性及推論影響，實際結果可能與預期不同。；海外拓點與投資案涉及當地法規、資金投入、合作進度與營運整合，具執行不確定性。；停車場案場續約、標案取得及大型商場經營權移轉，存在競爭與合約變動風險。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
