          "detailMarkdown": "## 7823 奧義賽博-KY創 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（51 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 1。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 1Q26 營收 NT$91.0M，年增 26.6%；簡報與轉錄一致。\n- 1Q26 毛利率 86.3%，較 4Q25 的 78.9% 回升，且仍維持高檔。\n- 1Q26 營業損失 NT$12.9M、稅後淨損 NT$4.9M，均較去年同期縮小。\n- 1Q26 底現金及約當現金 NT$764.5M，現金占總資產 88%。\n- 遞延收入加多年期訂單未開票金額 NT$363.7M，年增 22.36%。\n\n### 展望與成長利基\n- 公司預期台灣、日本為主要成長引擎，並提到日本市場今年可望高速成長。\n- 轉錄中提及 2026 年新夥伴包括日本 NTT Security、印度 Sectonics、泰國與馬來西亞合作夥伴。\n- AI 治理、模型安全與 AI Red Teaming 相關需求，將持續由金融、政府、航運等領域帶動。\n- 無人機反制市場被定位為第三支線，並連結關鍵基礎設施、大型活動與軍事應用。\n- 公司持續以策略合作與海外通路擴張作為中長期布局重點。\n\n### 產品、客戶與市場位置\n- 公司主軸仍聚焦於「三支箭」：資安韌性 AI、模型韌性 AI、國防/無人機反制 AI。\n- 管理層強調 1Q26 進入多條產品線同時推進階段，並稱第二支線已於 1Q26 順利出貨。\n- 公司將 AI 時代下的資安需求、AI 治理、AI Agent 風險與無人機安全視為主要成長主題。\n- 會中多次提及海外市場布局，尤其日本、泰國、印度與東南亞合作進展。\n- 公司預期台灣、日本為主要成長引擎，並提到日本市場今年可望高速成長。\n- AI 治理、模型安全與 AI Red Teaming 相關需求，將持續由金融、政府、航運等領域帶動。\n\n### 風險與不確定性\n- 簡報明確載明預測性資訊可能因市場需求、法規政策與整體經濟變化而與實際結果不同。\n- AI/資安/無人機相關新產品仍處商業化擴張期，出貨時程與市場接受度具不確定性。\n- 海外合作與在地化通路拓展仍在進行中，跨國落地進度可能受法規與市場條件影響。\n- 公司多次提到需持續投入研發與新賽道布局，顯示費用控制與成長投資間仍有平衡壓力。\n- AI Agent、模型安全等新興領域競爭快速，市場技術迭代風險高。\n- **需人工確認**：轉錄多次將「NTT Security」說成「NDD Security」，簡報與英文頁面皆為 **NTT Security**。\n- **需人工確認**：轉錄多次將「Mithos / Sittingware / Metros」等詞混用，疑似對應簡報中的 **Mythos**、**Shadow AI** 或其他產品/概念，需釐清。\n- **需人工確認**：轉錄提及「AI RIO」；簡報主線產品名稱為 **XCockpit / XecGuard / XecART / XecDefend**，AI RIO 是否為獨立產品或暫稱需確認。\n\n### Q&A 與管理層口氣\n- 管理層說明公司商業模式偏向依「保護的端點/帳號/企業數量」認列，而非傳統 SaaS 的使用人數。\n- 續約率在轉錄中提及約 99.5%，並強調客戶黏著度高。\n- 針對 Anthropic、OpenAI 等大型模型與相關工具，管理層認為攻擊成本下降將帶動資安需求上升。\n- 轉錄中提及 AI RIO 已有多家金融單位 POC，並預計 6、7 月後有首批集團客戶使用。\n- Q&A 亦提到公司對客戶的收費與產品採購彈性，強調可降低綁約感。\n\n### 評分利基點\n- 加分主因：管理層強調 1Q26 進入多條產品線同時推進階段，並稱第二支線已於 1Q26 順利出貨。；公司將 AI 時代下的資安需求、AI 治理、AI Agent 風險與無人機安全視為主要成長主題。；1Q26 毛利率 86.3%，較 4Q25 的 78.9% 回升，且仍維持高檔。。\n- 扣分或保留：簡報明確載明預測性資訊可能因市場需求、法規政策與整體經濟變化而與實際結果不同。；AI/資安/無人機相關新產品仍處商業化擴張期，出貨時程與市場接受度具不確定性。；海外合作與在地化通路拓展仍在進行中，跨國落地進度可能受法規與市場條件影響。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
