          "detailMarkdown": "## 2645 長榮航太 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1 營收為 **47.39 億元**，毛利 **13.05 億元**，營業淨利 **12.07 億元**，稅前淨利 **9.66 億元**，EPS **2.58 元**。\n- 簡報顯示 2026Q1 毛利率 **28%**、營業利益率 **24%**、純益率 **20%**，較 2025Q1 皆有提升。\n- 維修業務營收結構以**機體維修 57%**為主，其次為線上維修 13%、零件 12%、引擎 11%、其他 7%。\n- 製造業務營收結構以**引擎零件 83%**為主，機體 14%、其他 3%。\n- 資產負債表顯示現金及約當現金 **58.52 億元**、總資產 **246.44 億元**、總負債 **119.86 億元**、權益 **126.58 億元**。\n\n### 展望與成長利基\n- 維修產業方面，公司認為新機交機受供應鏈瓶頸影響，高齡機隊延後汰換，帶動 MRO 需求擴張。\n- 製造產業方面，簡報與口頭說明均指出 OEM 訂單能見度仍高，但引擎、航電與認證進度限制，使交機與產能擴張持續受限。\n- 引擎零件需求方面，LEAP、GEnx、GE9X、Passport 等主力機型需求持續，售後維修市場也隨全球機隊擴大而成長。\n- 維修策略上，將持續拓展歐洲市場，並深化與 Boeing、Airbus、GE 等客戶合作。\n- 製造策略上，空巴新案首件交付預計 2027Q1，波音新機型翼組件首件交付預計 2027Q3。\n\n### 產品、客戶與市場位置\n- 公司在維修與製造兩大業務主軸皆持續推進，並強調國際認證、客戶組合與產能布局。\n- 製造面則聚焦航太零組件、引擎零件，以及半導體設備零組件與無人載具等多角化布局。\n- 引擎零件需求方面，LEAP、GEnx、GE9X、Passport 等主力機型需求持續，售後維修市場也隨全球機隊擴大而成長。\n- 維修策略上，將持續拓展歐洲市場，並深化與 Boeing、Airbus、GE 等客戶合作。\n- 新機供給不足與機隊老化雖支撐維修需求，但也使市場景氣更受外部交機進度影響。\n- 空巴新合約與二廠進度：首件產品預計 **2027Q1** 交付；二廠與設備建置同步進行，預計 **2027Q3** 可投入零件製造。\n\n### 風險與不確定性\n- 供應鏈瓶頸持續，可能影響飛機製造商交機節奏與相關訂單轉化速度。\n- 新機供給不足與機隊老化雖支撐維修需求，但也使市場景氣更受外部交機進度影響。\n- 匯率波動曾影響獲利表現；管理層提到 2025Q2 美元急貶曾造成匯損擴大。\n- 製造擴產仍受原料、勞動力、認證與製程建置進度影響。\n- 轉投資公司整改與恢復狀況、以及新案量產時程仍有執行變數。\n- **需人工確認：** 口頭轉錄提到「2026Q1 已獲得 EASA A350 維修認證」，簡報亦寫「2026 Q1獲得EASA A350認證」，兩者一致；但若解讀為「維修認證」或其他細項證照，仍建議確認正式證照名稱。\n- **需人工確認：** 財務段口頭提到「本期淨利是 9,166 萬」，簡報表格顯示 2026Q1 本期淨利為 **966 百萬元**，兩者金額口語表述單位明顯一致為 **9.66 億元**，屬轉錄口誤，建議以簡報數字為準。\n- **需人工確認：** 口頭提到「全球機隊平均機齡 15.1 年」與簡報一致；另提到 2024 年 14.8 年、2025 年 14.9 年，與簡報未逐一列示，屬轉錄補充資訊。\n\n### Q&A 與管理層口氣\n- 轉投資公司長義發動機維修：管理層表示已完成自主整頓，產能逐步恢復，**2026Q1 已開始轉虧為盈**，全年預期可望獲利。\n- 空巴新合約與二廠進度：首件產品預計 **2027Q1** 交付；二廠與設備建置同步進行，預計 **2027Q3** 可投入零件製造。\n- 桃園國際機場不動產使用權資產：新增土地屬於棚廠前方停機位置，主要用於調度與符合自主管理要求，**非新棚廠建設計畫**。\n- 公司提及已取得 **EASA A350 維修認證**，首架客戶 A350 即將進廠維修。\n- 管理層也提到半導體設備零組件與商用無人載具為後續多角化發展方向。\n\n### 評分利基點\n- 加分主因：公司在維修與製造兩大業務主軸皆持續推進，並強調國際認證、客戶組合與產能布局。；管理層提到高齡機隊、供應鏈瓶頸與新機交機延宕，支撐維修需求維持。；Q&A 聚焦子公司改善進度、空巴訂單與二廠時程、桃園機場不動產使用權資產用途。。\n- 扣分或保留：供應鏈瓶頸持續，可能影響飛機製造商交機節奏與相關訂單轉化速度。；新機供給不足與機隊老化雖支撐維修需求，但也使市場景氣更受外部交機進度影響。；匯率波動曾影響獲利表現；管理層提到 2025Q2 美元急貶曾造成匯損擴大。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
