          "detailMarkdown": "## 6498 久禾光 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（78 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 4、保守訊號 0。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 2026-Q1 合併營收 345,005 千元，年增 35%。\n- 2026-Q1 稅後淨利 82,761 千元，年增 34%；EPS 為 1.75 元。\n- 2026/3/31 資產總計 2,581,647 千元，權益總計 1,454,567 千元。\n- 管理層說明毛利率變動與新產品良率調整有關。\n- 轉錄提到流動負債增加與現金股利發放相關；簡報未見完整拆解數字，需人工確認。\n\n### 展望與成長利基\n- 市場面：筆電出貨雖回歸穩定，但高屏占比、窄邊框與 AI PC 帶動鏡頭規格升級。\n- 產品面：新案由 5M 以下逐步往 5M、8M 以上高解析產品線移動。\n- 管理層表示 2026 年新案中，高階機種比重提升，ASP 與產品組合可能受益於規格升級。\n- 非筆電應用方面，智慧眼鏡、醫療、工業與智慧家居皆有案子推進。\n- 專利布局持續擴張，目標 2026 年累積 60 件。\n\n### 產品、客戶與市場位置\n- 主要成長動能仍以筆電光學鏡頭為主，並逐步延伸至醫療、智慧家庭、工業等應用。\n- 公司提到今年新開發的國際品牌客戶專案已陸續量產並開始貢獻營收。\n- 會中多次提及 AI PC、eUSB、5M/8M 高階鏡頭與智慧眼鏡等新應用機會。\n- 管理層說明毛利率變動與新產品良率調整有關。\n- 市場面：筆電出貨雖回歸穩定，但高屏占比、窄邊框與 AI PC 帶動鏡頭規格升級。\n- 產品面：新案由 5M 以下逐步往 5M、8M 以上高解析產品線移動。\n\n### 風險與不確定性\n- 2025-Q4 HBM 需求帶動 DDR、SSD 缺貨，可能影響部分機種料件供應與出貨節奏。\n- 客戶端新案導入與量產時程不確定，營收貢獻時間點仍待觀察。\n- 非筆電市場雖有開案增加，但是否轉化為營收仍受客戶進度影響。\n- 產品良率、製程調整與新產品導入，仍可能影響短期毛利表現。\n- 公司亦提及智慧眼鏡等新領域仍在試水溫階段，商業化時程具不確定性。\n- 轉錄提到「董事會通過配發現金股利 4.5 元」與「流動負債增加」的因果關係，簡報頁面未見對應說明，需人工確認。\n- 轉錄中曾出現「115年第一季」、「2026年第一季」及「165年第一季」等不同說法，依會議資訊與簡報主軸以 2026-Q1 為準；其餘疑似口誤標示需人工確認。\n- 轉錄提到「2026-Q1 合併資產負債表：資產總計 25億81164萬7000元、權益 14億5756萬7000元」與簡報數字大致一致，但口述有少量位數與單位混雜，需人工確認。\n\n### Q&A 與管理層口氣\n- 管理層說明毛利率變動與新產品良率調整有關。\n\n### 評分利基點\n- 加分主因：公司表示 2026 年第一季營收、獲利均創成立以來同期新高。；主要成長動能仍以筆電光學鏡頭為主，並逐步延伸至醫療、智慧家庭、工業等應用。；管理層強調微型化、高解析與客製化能力，作為與同業區隔的核心。。\n- 扣分或保留：2025-Q4 HBM 需求帶動 DDR、SSD 缺貨，可能影響部分機種料件供應與出貨節奏。；客戶端新案導入與量產時程不確定，營收貢獻時間點仍待觀察。；非筆電市場雖有開案增加，但是否轉化為營收仍受客戶進度影響。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
