          "detailMarkdown": "## 6869 雲豹能源 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 1Q26 合併營收 NT$16.64 億，年增 67%；毛利率 18.6%，較 1Q25 增加 6.8 個百分點。\n- 1Q26 合併營業利益 NT$1.31 億；歸屬母公司淨損 NT$1.33 億，管理層說明主要受轉投資評價影響。\n- 1Q26 營收組成以工程、售電、儲能工程為主，海外營收占比約 26%。\n- 2025 年全年營收 NT$74.69 億；2021–2025 年營收複合成長率簡報列示為高成長。\n- 2026/3/31 資產總額 NT$157.11 億，權益總額 NT$50.54 億，負債比相對去年同期上升。\n\n### 展望與成長利基\n- 日本儲能與綠電交易被列為未來兩年主要高能見度成長來源。\n- 擬收購 BlackRock 旗下 GIP 在台已商轉太陽能案場群，總裝置容量 187MW，預計 3Q26 完成。\n- AIDC 預計自今年起開始貢獻營收，管理層稱明年可望進一步放大。\n- 海外方面，澳洲儲能已啟動布局，東南亞光電案場持續推進，部分地區已開始貢獻營收。\n- 水處理、SOFC 分散式能源、資產管理與維運等業務被定位為補充型成長動能。\n\n### 產品、客戶與市場位置\n- 公司主軸仍圍繞綠能、儲能、售電、水處理與循環經濟，並新增子公司「雲豹超算」切入 AIDC。\n- 管理層表示，AIDC 方向鎖定供電、營運與算力租賃等環節，強調土地、電力與綠電整合能力。\n- 子公司資本市場進程同步推進：天能綠電已上櫃，台普威預計 5/27 登錄興櫃。\n- 會中多次提及海外市場與資產併購，包含日本、澳洲、東南亞及台灣已商轉案場整併。\n- AIDC 預計自今年起開始貢獻營收，管理層稱明年可望進一步放大。\n- 水處理、SOFC 分散式能源、資產管理與維運等業務被定位為補充型成長動能。\n\n### 風險與不確定性\n- AIDC 市場仍受電力供給、併網條件、土地取得與法規進度影響。\n- 日本與澳洲儲能擴張、海外專案開工與併網時程，存在執行與市場不確定性。\n- 綠電市場競爭加劇，管理層提到供需仍偏緊，但價格、供給與客戶取得均具變數。\n- 收購 187MW 太陽能案場群仍待 3Q26 交割完成，後續整併與修繕進度需觀察。\n- 魚電共生、水處理、循環經濟等專案亦受政府政策與工程進度影響。\n- 1Q26 文字說明出現「合併營業利益 NT$1.31 億」，但語音轉錄曾口語誤述為「11.31 億」；依簡報數字校正為 NT$1.31 億。\n- 1Q26 歸屬母公司淨損，簡報與語音一致為 NT$1.33 億；但轉錄部分段落曾口語誤述為「淨利」語意，需以簡報表格為準。\n- AIDC 市場規模簡報寫「超過 NT$9,512 億」且轉錄提及約 9,500 億，數字大致一致。\n\n### Q&A 與管理層口氣\n- 1Q26 合併營收 NT$16.64 億，年增 67%；毛利率 18.6%，較 1Q25 增加 6.8 個百分點。\n\n### 評分利基點\n- 加分主因：管理層表示，AIDC 方向鎖定供電、營運與算力租賃等環節，強調土地、電力與綠電整合能力。；2026 年為營運擴張與新事業落地並行的一年，並多次提及 2026–2027 年延續成長。；2025 年全年營收 NT$74.69 億；2021–2025 年營收複合成長率簡報列示為高成長。。\n- 扣分或保留：AIDC 市場仍受電力供給、併網條件、土地取得與法規進度影響。；日本與澳洲儲能擴張、海外專案開工與併網時程，存在執行與市場不確定性。；綠電市場競爭加劇，管理層提到供需仍偏緊，但價格、供給與客戶取得均具變數。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
