          "detailMarkdown": "## 6576 逸達 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 0、保守訊號 0。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- **CAMCEVI 42 mg（6 個月劑型）** 已於美國上市，並持續透過授權夥伴在歐洲等市場供貨。\n- **CAMCEVI ETM / 21 mg（3 個月劑型）** 已取得美國、加拿大與歐盟藥證，預計 2026 年下半年至年底陸續上市。\n- 管理層表示，2026 年第一季已完成 **MMP12 資產切出**，並認列 **5 億多元業外收益**；此段為轉錄內容，金額需人工確認。\n- 公司提到，2026 年整體費用預期較 2025 年下降，主因包括部分專案停止、資產切出，以及組織調整。\n- 目前營收結構仍以 **供貨收入、權利金與里程碑金** 為主，且未來若達成重要節點，將依規定揭露拆分內容。\n\n### 展望與成長利基\n- **CAMCEVI 42 mg / 21 mg** 將持續擴張市場覆蓋，並藉由不同劑型與適應症推進，朝 franchise 化發展。\n- **CPP（兒童中樞性性早熟）** 目標於 2026 年下半年向美國 FDA 提交 NDA，並規劃後續商業化模式。\n- **FP-016（VMAT2 LAI）** 與 **FP-018（Cariprazine LAI）** 預計 2027 年進入人體臨床，屬公司中期 CNS 成長主軸。\n- **Mirivadelgat（FP-045 / ALDH2）** 仍在第二期臨床收案中，目標鎖定 PH-ILD 與後續 follow-on 產品。\n- NCE 端公司規劃以 **NewCo / 授權 / 股權參與** 的方式延伸長期價值，而非單純內部全包開發。\n\n### 產品、客戶與市場位置\n- 管理層表示，2026 年起公司重點將從單一產品，逐步走向 **CAMCEVI franchise** 與多條產品線並進。\n- 會中提到公司對外合作、授權與里程碑收入模式仍將持續，並以美國市場為主要優先目標。\n- 管理層強調，**新劑型與新製程開發** 是 505(b)(2) 產品的核心難點，但也是產品差異化與商業化價值的基礎。\n- **CAMCEVI 42 mg（6 個月劑型）** 已於美國上市，並持續透過授權夥伴在歐洲等市場供貨。\n- **CAMCEVI ETM / 21 mg（3 個月劑型）** 已取得美國、加拿大與歐盟藥證，預計 2026 年下半年至年底陸續上市。\n- **CAMCEVI 42 mg / 21 mg** 將持續擴張市場覆蓋，並藉由不同劑型與適應症推進，朝 franchise 化發展。\n\n### 風險與不確定性\n- 簡報明確列出前瞻性聲明，指出實際結果可能因 **風險、不確定性與外部因素** 而不同。\n- **供應鏈與製造** 仍是關鍵不確定性，包含法國代工廠整改、產能升級、以及技轉至夥伴的時程。\n- **CPP 自建銷售或授權** 的模式尚在評估，後續若採自營，行銷與市場導入費用可能上升。\n- **FP-016 / FP-018** 雖被公司描述為高潛力案，但其核心風險仍是長效注射劑的 PK 穩定性與劑型開發難度。\n- **MMP12、ALDH2** 等新藥若屬 first-in-class 或 target 尚未完全驗證，臨床與授權不確定性較高。\n- **需人工確認：CAMCEVI 21 mg 藥證/上市時程**\n- 簡報英文版寫法為 **2025/8 取得美國藥證、2026 Q4 美國上市**；中文口說部分一度講成「今年年底上市」，後段又提到 **2026 年下半年/第四季**，存在時點混用。\n- **需人工確認：CPP NDA 提交時間**\n\n### Q&A 與管理層口氣\n- Q&A 中，公司也補充了 CPP、FP-016、FP-018 與 MMP12/ALDH2 等資產的推進邏輯與資源配置。\n- 公司提到，2026 年整體費用預期較 2025 年下降，主因包括部分專案停止、資產切出，以及組織調整。\n- **供應鏈與製造** 仍是關鍵不確定性，包含法國代工廠整改、產能升級、以及技轉至夥伴的時程。\n- **CPP 自建銷售或授權** 的模式尚在評估，後續若採自營，行銷與市場導入費用可能上升。\n\n### 評分利基點\n- 加分主因：管理層強調，**新劑型與新製程開發** 是 505(b)(2) 產品的核心難點，但也是產品差異化與商業化價值的基礎。；**FP-016（VMAT2 LAI）** 與 **FP-018（Cariprazine LAI）** 預計 2027 年進入人體臨床，屬公司中期 CNS 成長主軸。；**FP-016 / FP-018** 雖被公司描述為高潛力案，但其核心風險仍是長效注射劑的 PK 穩定性與劑型開發難度。。\n- 扣分或保留：簡報明確列出前瞻性聲明，指出實際結果可能因 **風險、不確定性與外部因素** 而不同。；**供應鏈與製造** 仍是關鍵不確定性，包含法國代工廠整改、產能升級、以及技轉至夥伴的時程。；**CPP 自建銷售或授權** 的模式尚在評估，後續若採自營，行銷與市場導入費用可能上升。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
