          "detailMarkdown": "## 7810 捷創科技 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（78 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 4、保守訊號 0。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 2026Q1 營收為 **174,255 千元**，QoQ 低於 2025Q4 的 226,012 千元；公司說明主因為前一季的單一大案已於 Q1 大致出貨完畢。\n- 2026Q1 毛利率 **50.24%**，淨利 **37,125 千元**，EPS **1.83 元**；YoY 皆有成長。\n- 2026/03/31 現金及約當現金 **751,421 千元**，資產總計 **1,176,034 千元**，權益總計 **983,956 千元**，每股淨值 **48.59 元**。\n- 轉錄提到自有產品比重已達約三成，工程服務約六成五；簡報亦顯示工程服務/維修與自有產品收入均較前一年增加。\n- 存貨較去年同期增加，管理層說明與自有產品出貨準備、CLAMPER 相關備貨及裝機需求有關。\n\n### 展望與成長利基\n- 公司表示 2026 年希望月營收平均維持在 **5,000–6,000 萬元以上**，並朝 **每月 6,000 萬元以上**目標前進。\n- 毛利率目標希望維持在 **五成左右或更好**，淨利率希望維持 **兩成以上**。\n- Q2 展望方面，管理層提到 4 月表現較佳，後續月份希望維持在相近水準。\n- 後續動能來源包括：裝機需求、記憶體廠延壽設備維修、搬運機器需求、CLAMPER 出貨、海外新廠案與工程服務延伸。\n- 管理層亦提到中長期希望工程服務與自有產品的比重持續改善，朝更平衡的結構發展。\n\n### 產品、客戶與市場位置\n- 公司說明 2026 年第一季營運概況，主軸涵蓋工程服務/維修、自有產品與實驗室自動化業務。\n- 第一季營收、毛利與獲利較去年同期成長，產品組合中自有產品比重提高。\n- 管理層提到 4 月營收跳升，主因包含裝機需求增加、維修需求提升及自有產品出貨。\n- 轉錄提到自有產品比重已達約三成，工程服務約六成五；簡報亦顯示工程服務/維修與自有產品收入均較前一年增加。\n- 存貨較去年同期增加，管理層說明與自有產品出貨準備、CLAMPER 相關備貨及裝機需求有關。\n- 後續動能來源包括：裝機需求、記憶體廠延壽設備維修、搬運機器需求、CLAMPER 出貨、海外新廠案與工程服務延伸。\n\n### 風險與不確定性\n- 產品組合仍是毛利率的重要變動因素，自有產品比重若不足，毛利率改善幅度可能受限。\n- 人力與交付能力可能受裝機需求增加影響，公司提到會持續招募並將部分周邊工作外包。\n- 自有產品交期受零組件供應影響，轉錄提到部分產品交期約 2–3 個月，工業電腦板件取得可能是瓶頸。\n- CLAMPER、測試探針相關技術與市場擴張仍存在技術門檻與應用不確定性。\n- 簡報免責聲明指出，前瞻性資訊受成本、需求、政策法規與經濟金融環境變動影響。\n- **需人工確認：公司名稱**\n- 轉錄多次出現「結狀科技」，簡報與會議資訊為 **7810 捷創科技** / **Jtron Technology Corp.**，疑似語音辨識誤植。\n- **需人工確認：營收口徑**\n\n### Q&A 與管理層口氣\n- 2026Q1 毛利率 **50.24%**，淨利 **37,125 千元**，EPS **1.83 元**；YoY 皆有成長。\n- 毛利率目標希望維持在 **五成左右或更好**，淨利率希望維持 **兩成以上**。\n- 產品組合仍是毛利率的重要變動因素，自有產品比重若不足，毛利率改善幅度可能受限。\n- 簡報免責聲明指出，前瞻性資訊受成本、需求、政策法規與經濟金融環境變動影響。\n- **需人工確認：毛利率敘述**\n- 轉錄提到 2025 年毛利率約 **50.1%**，簡報圖表頁面顯示 **49.0%** 或 **50.2%** 的不同版本，可能為不同圖表標示或轉錄口誤。\n\n### 評分利基點\n- 加分主因：第一季營收、毛利與獲利較去年同期成長，產品組合中自有產品比重提高。；管理層提到 4 月營收跳升，主因包含裝機需求增加、維修需求提升及自有產品出貨。；會中另說明有部分海外新廠與新案帶動後續出貨動能。。\n- 扣分或保留：產品組合仍是毛利率的重要變動因素，自有產品比重若不足，毛利率改善幅度可能受限。；人力與交付能力可能受裝機需求增加影響，公司提到會持續招募並將部分周邊工作外包。；自有產品交期受零組件供應影響，轉錄提到部分產品交期約 2–3 個月，工業電腦板件取得可能是瓶頸。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
