          "detailMarkdown": "## 7786 東方風能 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 1Q26 營收為 NT$1,773 百萬元，年增 53.8%；營業毛利 NT$351 百萬元，年增 19.4%。\n- 1Q26 營業利益 NT$280 百萬元，年增 19.7%；稅後淨利 NT$211 百萬元，年減 17.3%。\n- 1Q26 EPS 為 NT$1.20；業外損益主要受匯兌波動影響。\n- 2026/03/31 現金及約當現金為 NT$695 百萬元，較去年同期下降；公司說明主因為持續投入船舶建造與設備升級。\n- 2026/03/31 總資產為 NT$16,609 百萬元，較去年同期顯著增加，反映投資成長階段。\n\n### 展望與成長利基\n- 2Q–3Q26 海事工程進入施工高峰，船隊預期全力運轉，毛利率有機會回升。\n- 改裝後的佈纜船將投入較高附加價值專案，帶動業務組合優化。\n- 通訊海纜專案將進入主要工程認列階段，簡報預期於第三季完成建置。\n- 2026 年底至 2028 年將有 5 艘大型工程船陸續投運，目標是提升高毛利業務占比並擴大規模效益。\n\n### 產品、客戶與市場位置\n- 中長期主軸為離岸風電、天然氣能源、通訊海纜三大業務並進，並透過新船加入推進全球布局。\n- 法說簡報明列前瞻性資訊具風險與不確定性，未來實際結果可能受市場需求、價格波動、國際情勢與政策變化影響。\n\n### 風險與不確定性\n- 法說簡報明列前瞻性資訊具風險與不確定性，未來實際結果可能受市場需求、價格波動、國際情勢與政策變化影響。\n- 語音轉錄提及匯率波動對業外結果造成影響，顯示外匯風險仍具不確定性。\n- 轉錄提到台灣離岸風電產業面臨「電價」與開發商退場等議題，反映產業環境仍有變數。\n- 大型船舶建造、改裝與交付時程若有延誤，可能影響營運配置與認列節奏。\n- 需人工確認：轉錄提到「第一季稅後淨利為 2.51 億元」，簡報數字為 NT$211 百萬元，兩者不一致。\n- 需人工確認：轉錄提到「現金翻倍到 100 億元」，簡報 2026/03/31 現金及約當現金為 NT$695 百萬元，與該敘述不符。\n- 需人工確認：轉錄中多處船舶名稱被辨識為「highlight 程式、固展船、DP Ocean、DESOS、VIP、TPCI、CIM」等，疑似對應英文專有名詞或船型名稱，需回查原始音檔或簡報。\n- 需人工確認：轉錄提及 2025 年獲利與 EPS 數字、現金股利與配息率敘述，簡報僅顯示股利趨勢圖，未完整列示文字說明。\n\n### Q&A 與管理層口氣\n- 第二、三季預期進入施工高峰，船隊將全面投入營運，毛利率有望回升至去年旺季水準。\n- 2Q–3Q26 海事工程進入施工高峰，船隊預期全力運轉，毛利率有機會回升。\n\n### 評分利基點\n- 加分主因：第一季營收年增 54%，主要來自離岸風場工程需求優於預期，以及通訊海纜專案依完工比例法認列。；第二、三季預期進入施工高峰，船隊將全面投入營運，毛利率有望回升至去年旺季水準。；2026/03/31 總資產為 NT$16,609 百萬元，較去年同期顯著增加，反映投資成長階段。。\n- 扣分或保留：法說簡報明列前瞻性資訊具風險與不確定性，未來實際結果可能受市場需求、價格波動、國際情勢與政策變化影響。；語音轉錄提及匯率波動對業外結果造成影響，顯示外匯風險仍具不確定性。；轉錄提到台灣離岸風電產業面臨「電價」與開發商退場等議題，反映產業環境仍有變數。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
