          "detailMarkdown": "## 2483 百容 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（51 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 1。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 1Q26 合併營收 4.81 億元，年增 14%；營業毛利 6,355 萬元，毛利率 13.23%。\n- 營業費用 6,498 萬元，年減 9%；營業損失 143 萬元，較去年同期明顯改善。\n- 稅前損益 1,486 萬元；本期淨利 1,661 萬元；歸屬母公司淨利 1,604 萬元。\n- EPS 為 0.15 元。\n- 語音轉錄提到半導體產品營收約 2.42 億元、占比約 51%；母公司與中國大陸子公司營收皆較去年同期增加。\n\n### 展望與成長利基\n- 半導體相關產品將持續朝電動車與機車市場應用開發高功率產品。\n- 公司表示將持續關注第三代半導體，如碳化矽（SiC）與氮化鎵（GaN）應用。\n- 電動車充電設備及相關電源應用的智慧功率模組導線架，將持續開發。\n- 高效能應用的散熱需求將推動 BGA 均溫片產品開發。\n- 產品設計與應用方向將配合客戶需求調整。\n\n### 產品、客戶與市場位置\n- 公司簡介聚焦於繼電器、開關、連接器、保險絲、衝壓件、步進馬達與半導體導線架等產品線。\n- 語音轉錄提到公司歷史與產品發展，並說明台灣、中國與美國據點配置。\n- 展望聚焦高功率、第三代半導體、電動車充電設備、智慧功率模組與散熱相關產品。\n- 語音轉錄提到半導體產品營收約 2.42 億元、占比約 51%；母公司與中國大陸子公司營收皆較去年同期增加。\n- 半導體相關產品將持續朝電動車與機車市場應用開發高功率產品。\n- 公司表示將持續關注第三代半導體，如碳化矽（SiC）與氮化鎵（GaN）應用。\n\n### 風險與不確定性\n- 轉錄提及歐洲與美洲區域營收下滑，區域需求復甦情況未明。\n- 半導體、車用與電源應用開發進度及導入時程未揭露。\n- 價格競爭、產品組合變化與成本波動影響未揭露。\n- 未說明後續訂單能見度與下季營運目標。\n- 未揭露具體資本支出、產能擴充或庫存風險資訊。\n- **需人工確認：公司英文名歷史頁簡報與轉錄**\n- 簡報頁面顯示「1980 ECE founded / Capital $100,000」，轉錄則說「1981 年成立、資本額 300 萬」；年份與資本額不一致。\n- **需人工確認：產品/事業群歷史時間點**\n\n### Q&A 與管理層口氣\n- 簡報列示 Q&A，但提供內容中未包含實際問答紀錄。\n- 會後聯絡資訊：發言人蔡荻宜協理，電話 04-23598668 分機 1272。\n- Email：judy@mail.ece.com.tw。\n- 未揭露其他補充說明。\n\n### 評分利基點\n- 加分主因：營運面顯示 1Q26 營收年增，毛利率改善，且由去年同期虧損轉為獲利。；展望聚焦高功率、第三代半導體、電動車充電設備、智慧功率模組與散熱相關產品。；營業費用 6,498 萬元，年減 9%；營業損失 143 萬元，較去年同期明顯改善。。\n- 扣分或保留：轉錄提及歐洲與美洲區域營收下滑，區域需求復甦情況未明。；半導體、車用與電源應用開發進度及導入時程未揭露。；價格競爭、產品組合變化與成本波動影響未揭露。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
