          "detailMarkdown": "## 3622 洋華 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（58 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 1。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- **2025 年合併營收 17.26 億元**，年增 9%；**營業淨利 4.83 億元**，年增 3%。\n- **2025 年稅前淨利 10.38 億元**、**本期淨利 9.70 億元**、**歸屬母公司淨利 9.22 億元**。\n- **2026Q1 營收 3.63 億元**，季減 16%、年減 3%；**歸屬母公司淨利 1.65 億元**，**EPS 1.09 元**。\n- Q1 資產結構中，**現金與約當現金 6.54 億元**、**有價證券與權益法投資 50.59 億元**、**黃金部位 8.86 億元**。\n- Q1 **流動負債 10.33 億元**明顯高於去年底，管理層表示主因是將今年配息相關應付股利於 Q1 認列。\n\n### 展望與成長利基\n- 光電業務方面，Q2 與 4 月表現「符合預期」，主要成長動能來自 **博弈機 Monitor** 與 **大尺寸應用**。\n- 博弈機 Monitor 需求預期可延續至年底，且既有機種與新機種都有持續需求。\n- 大尺寸運動器材應用屬專案性質，後續能見度仍需視終端客戶拉貨情況。\n- 機電事業群今年前段拉貨較慢，但公司表示傳統上 **下半年通常會回補**。\n- 對日本原廠代工部分，公司表示今年將 **陸續增加品項** 以對應市場需求。\n\n### 產品、客戶與市場位置\n- 大尺寸運動器材應用屬專案性質，後續能見度仍需視終端客戶拉貨情況。\n- 對日本原廠代工部分，公司表示今年將 **陸續增加品項** 以對應市場需求。\n- 海外客戶、日本原廠代工與博弈機相關需求，仍受終端市場變化影響。\n- 日本原廠代工：公司表示今年會持續增加品項，以滿足市場需求。\n\n### 風險與不確定性\n- 大尺寸運動器材相關訂單屬專案性質，需求延續度與時點較不易掌握。\n- 機電事業群拉貨受其他部門推進影響而延後，回補時程仍存在不確定性。\n- Q1 流動負債上升與配息認列有關，雖屬會計處理因素，但仍可能影響短期財務比率觀感。\n- 業外收益占比高，2025 年獲利結構受非營業項目影響較大，後續波動需留意。\n- 海外客戶、日本原廠代工與博弈機相關需求，仍受終端市場變化影響。\n- **需人工確認：2025 年 EPS**\n- 簡報：**6.09 元**\n- 轉錄：**16.09 元**\n\n### Q&A 與管理層口氣\n- 博弈機與大尺寸應用的成長來源：管理層指出主要來自 **4 月光電部門**，尤其是博弈機 Monitor 與大尺寸運動器材。\n- 博弈機需求延續性：公司認為 **到年底應可維持穩定成長**。\n- 投資陳宏光電的效益：公司提到可增加組裝與工程合作，並有助於往 **Monitor / 整機 / CLCN / 電子紙** 等方案延伸。\n- 日本原廠代工：公司表示今年會持續增加品項，以滿足市場需求。\n- **機電事業訂單約 30 億元、出貨期間**：轉錄中提到提問，但**未見完整回覆，未揭露**。\n\n### 評分利基點\n- 加分主因：2025 年整體營收與獲利皆較 2024 年成長；營業外收支貢獻顯著，為稅前淨利主要來源之一。；Q1 **流動負債 10.33 億元**明顯高於去年底，管理層表示主因是將今年配息相關應付股利於 Q1 認列。；光電業務方面，Q2 與 4 月表現「符合預期」，主要成長動能來自 **博弈機 Monitor** 與 **大尺寸應用**。。\n- 扣分或保留：大尺寸運動器材相關訂單屬專案性質，需求延續度與時點較不易掌握。；機電事業群拉貨受其他部門推進影響而延後，回補時程仍存在不確定性。；Q1 流動負債上升與配息認列有關，雖屬會計處理因素，但仍可能影響短期財務比率觀感。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
