          "detailMarkdown": "## 3703 欣陸 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（59 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 3、保守訊號 2。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 合併營收 63.61 億元，較 1Q25 的 74.03 億元減少 14.1%。\n- 營業毛利 9.15 億元，毛利率 14.4%，年增 4.2 個百分點。\n- 營業利益 3.24 億元，營業利益率 5.1%；歸屬母公司淨利 2.71 億元，純益率 4.3%。\n- EPS 0.33 元，較去年同期 0.05 元增加。\n- 2026/3/31 現金及約當現金 105.27 億元；資產總計 966.78 億元，權益總計 288.09 億元。\n- 短期及一年內到期計息負債 226.64 億元、長期計息負債 171.24 億元；存貨 344.28 億元，仍為主要資產項目。\n\n### 展望與成長利基\n- 不動產開發事業方面，4 月公開銷售台北大安區住宅案「衡昀」，5 月公開銷售台中南屯區住宅案「秴楓」。\n- 2026 至 2029 年可認列住宅案持續增加，包含多個已銷售或持續銷售中的專案。\n- 2030 年以後的儲備案包含台北、新北、新竹、台中及高雄多項規劃中土地／建案。\n- 營建工程在手案以捷運、軌道、住宅與複合式建築為主，2026 年主要專案清單維持完整。\n- 環境工程及水資源處理方面，嘉義二期 EPC 已取得，預計 2029 年完工；橋頭與成溪案進入收尾或營運轉換階段，未來營運收入可望持續堆疊。\n\n### 產品、客戶與市場位置\n- 不動產開發案的銷售速度、交屋時點與市場需求，會影響營收與獲利認列。\n- 簡報免責聲明提及市場需求、價格波動、競爭、國際經濟、供應鏈與匯率等均可能造成實際結果差異。\n\n### 風險與不確定性\n- 營收與獲利受各事業體不同營運週期影響，尤其工程案在新建、收尾、營運轉換期的認列節奏不一。\n- 不動產開發案的銷售速度、交屋時點與市場需求，會影響營收與獲利認列。\n- 環工案雖可提供長期營運收入，但短期工程營收可能因進度變化而上下波動。\n- 簡報免責聲明提及市場需求、價格波動、競爭、國際經濟、供應鏈與匯率等均可能造成實際結果差異。\n- 對台南推案、企業總部建築案、以及更多私人／公辦水資源案件仍處於評估階段，未定案前具不確定性。\n- **需人工確認：轉錄中「台中的豐石」與簡報頁面顯示的「豐蒔」可能為同案不同聽打字形，建議核對正式案名。**\n- **需人工確認：轉錄中提及「捐稅」案名，簡報頁面顯示為「鐫萃」，推測為同案不同辨識結果。**\n- **需人工確認：轉錄中提及「衡雲／橫雲」與簡報頁面「衡昀」可能為同一專案，案名需以公司正式揭露為準。**\n\n### Q&A 與管理層口氣\n- 營業毛利 9.15 億元，毛利率 14.4%，年增 4.2 個百分點。\n- 簡報免責聲明提及市場需求、價格波動、競爭、國際經濟、供應鏈與匯率等均可能造成實際結果差異。\n\n### 評分利基點\n- 加分主因：2026年第一季合併營收 63.61 億元，年減 14.1%，但毛利、營業利益與稅後淨利均較去年同期明顯改善。；第一季歸屬母公司淨利 2.71 億元，EPS 0.33 元；簡報與轉錄均指出獲利成長主要來自不動產開發事業交屋認列增加。；公司強調資產負債表維持穩健，並持續以營收存量與在手專案支撐後續年度的營運。。\n- 扣分或保留：營收與獲利受各事業體不同營運週期影響，尤其工程案在新建、收尾、營運轉換期的認列節奏不一。；不動產開發案的銷售速度、交屋時點與市場需求，會影響營收與獲利認列。；環工案雖可提供長期營運收入，但短期工程營收可能因進度變化而上下波動。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
