          "detailMarkdown": "## 4438 廣越 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（86 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 6、保守訊號 1。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 1Q26 營收 NT$27.77 億，年增 0.7%，為歷史同期次高。\n- 1Q26 毛利 NT$3.31 億、營業利益 NT$0.89 億；每股虧損收斂至 NT$0.04。\n- 4 月營收 NT$15 億，年增 37%；前 4 月營收 NT$42.7 億，年增 11%，皆創歷史同期新高。\n- 1Q26 毛利率 11.9%、營業利益率 -3.2%、淨利率 -0.2%；與 1Q25 相較，虧損幅度縮小。\n- 資產負債表顯示 1Q26 總資產 NT$194.6 億、總負債 NT$87.4 億、總權益 NT$107.1 億；現金 NT$18.2 億。\n\n### 展望與成長利基\n- 公司預期在營收成長、製造效率改革、低效資產優化持續推進下，獲利有機會挑戰 2022 疫情高峰以外的歷史高點。\n- 2026 年營業利益率目標為 6% 以上。\n- 管理層表示約旦基地將成為中期成長引擎，並持續支撐北美訂單承接。\n- 中長期目標包含：5 年內 ROE 提升至 20%，並維持 70% 配息率。\n- 產業整併趨勢被視為有利於公司擴大競爭優勢。\n\n### 產品、客戶與市場位置\n- 轉錄提及美國對等關稅、暫時性關稅及未來退稅進度，相關政策變化具不確定性。\n- 轉錄提及匯率波動對 2025 年獲利造成影響，後續仍受外匯市場變動影響。\n- 約旦新廠投產時程與產能爬坡仍受建廠、招工與客戶訂單節奏影響。\n- 產業整併與品牌客戶下單轉移雖有利，但需求與訂單集中度仍具變動性。\n\n### 風險與不確定性\n- 轉錄提及美國對等關稅、暫時性關稅及未來退稅進度，相關政策變化具不確定性。\n- 轉錄提及越南廠曾發生火災，損失回補與後續認列時點仍有不確定性。\n- 轉錄提及匯率波動對 2025 年獲利造成影響，後續仍受外匯市場變動影響。\n- 約旦新廠投產時程與產能爬坡仍受建廠、招工與客戶訂單節奏影響。\n- 產業整併與品牌客戶下單轉移雖有利，但需求與訂單集中度仍具變動性。\n- 需人工確認：簡報寫「約旦出貨比重 2025 年由 8% 提升至 17%，預估 2026 年突破 20%」；轉錄口述為「2025 年提升到 17%，今年有望突破到 28%」。\n- 需人工確認：簡報寫約旦新廠「其中 2 層預計 3Q26 完成」；轉錄口述出現「6 月完工、7/8 月裝置完成、第三基地可投入生產」等較細時程，與簡報不完全一致。\n- 需人工確認：簡報寫新廠樓地板面積 16,000 平方公尺；轉錄一度口述為「1690 平方米」，疑似口誤或轉錄誤差。\n\n### Q&A 與管理層口氣\n- 1Q26 毛利率 11.9%、營業利益率 -3.2%、淨利率 -0.2%；與 1Q25 相較，虧損幅度縮小。\n- 管理層表示約旦基地將成為中期成長引擎，並持續支撐北美訂單承接。\n- 轉錄提及美國對等關稅、暫時性關稅及未來退稅進度，相關政策變化具不確定性。\n- 約旦新廠投產時程與產能爬坡仍受建廠、招工與客戶訂單節奏影響。\n- 產業整併與品牌客戶下單轉移雖有利，但需求與訂單集中度仍具變動性。\n- 需人工確認：轉錄提及 2025 年火災損失、對等關稅退還、匯損等細項，簡報僅概述「最壞已過」與效率改革，未逐項揭露。\n\n### 評分利基點\n- 加分主因：公司主軸為「最壞已過、重塑效率、重構價值」，聚焦營運改善與中長期成長。；1Q26 虧損明顯收斂，且 4 月營收續創同期新高，顯示季節性淡旺季循環下的回升動能。；管理層目標為提升營業利益率、提高 ROE，並維持較高配息率。。\n- 扣分或保留：轉錄提及美國對等關稅、暫時性關稅及未來退稅進度，相關政策變化具不確定性。；轉錄提及越南廠曾發生火災，損失回補與後續認列時點仍有不確定性。；轉錄提及匯率波動對 2025 年獲利造成影響，後續仍受外匯市場變動影響。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
