          "detailMarkdown": "## 4541 晟田 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026 年累計至 4 月營收 6.18 億元，年增 34.71%。\n- 2026 年 1 至 4 月營收結構：航太客供 49%、航太自購 25%、半導體 24%、其他 2%。\n- 各業務累計至 4 月營收：航太客供料 2.99 億元（年增 30.67%）、航太自購料 1.54 億元（年增 74.60%）、半導體設備零組件 1.50 億元（年增 53.78%）、其他精密零組件 0.14 億元（年減 67.39%）。\n- 口頭提及 1 至 4 月整體毛利率約 23%，第一季財報毛利率約 20% 多，4 月毛利率相對較高。\n- 軍工相關營收：2025 年約 8,389 萬元；2026 年累計至 4 月約 1,105 萬元。\n\n### 展望與成長利基\n- 航太方面：客機引擎零件需求持續提升，訂單確認度高。\n- 半導體方面：AI 應用帶動先進製程設備投資，零組件需求維持穩定提升。\n- 公司 2026 年預計營收比例為：航太客供 52%、航太自購 20%、半導體 23%、其他 5%。\n- 口頭說明提到，因應客戶增產需求，規劃資本支出與產能擴充，預期可於明年第二季開始產生營收貢獻。\n- 軍工與維修業務持續發展，並配合 CMMC 2.0 等資安要求推進。\n\n### 產品、客戶與市場位置\n- 會議主軸為「第一季營運概況、產業近況與後續展望」，並補充航太、半導體與軍工相關進展。\n- 公司認為航太產業受惠於民航機交機與維修需求，整體市場需求仍具韌性。\n- 半導體設備零組件需求則受 AI 相關資本支出帶動，呈現穩定成長。\n- 2026 年 1 至 4 月營收結構：航太客供 49%、航太自購 25%、半導體 24%、其他 2%。\n- 各業務累計至 4 月營收：航太客供料 2.99 億元（年增 30.67%）、航太自購料 1.54 億元（年增 74.60%）、半導體設備零組件 1.50 億元（年增 53.78%）、其他精密零組件 0.14 億元（年減 67.39%）。\n- 半導體方面：AI 應用帶動先進製程設備投資，零組件需求維持穩定提升。\n\n### 風險與不確定性\n- 航太供應鏈仍受波音、空巴及發動機交付節奏影響，實際拉貨與交機可能波動。\n- 美國關稅、232 條款與相關政策仍有後續審查與執行不確定性。\n- 半導體設備需求雖成長，但仍需觀察客戶資本支出節奏與終端需求變化。\n- 軍工業務受認證、客戶審查與法規要求影響，導入進度可能較長。\n- 口頭說明中多次提及產能、月產與認證時程，部分與簡報版本不完全一致，需再核對。\n- **需人工確認**：簡報第 29 頁寫 2026 累計至 4 月半導體設備零組件營收為 **1.50 億**、年增 **53.78%**；語音轉錄曾出現「1,000 多萬」與其他數值表述，疑似轉錄誤差。\n- **需人工確認**：簡報第 29 頁寫 2026 年預計營收比例為 **52:20:23:5**；口頭說明中一度提到「平衡」或其他調整方向，但未形成一致定稿。\n- **需人工確認**：口頭提及資本支出合計 **6.77 億**，拆分為設備 **2.66 億**、廠房 **4.1 億**，與簡報未見對應頁面逐字揭露，需確認是否為最新董事會核准數。\n\n### Q&A 與管理層口氣\n- 口頭提到 5 月董事會已通過資本支出案，設備約 2.66 億元、廠房約 4.1 億元，合計約 6.77 億元。\n- 資本支出主因為漢翔相關、GE 體系引擎零組件增量需求，預期不需重新認證，時程相對明確。\n- 口頭補充毛利率差異主要來自產品組合：客供料與自購料、製造料等結構不同。\n- 口頭對軍工業務表示仍屬早期階段，相關營收規模尚小。\n- 會議最後未再揭露其他新增財務數據。\n\n### 評分利基點\n- 加分主因：公司認為航太產業受惠於民航機交機與維修需求，整體市場需求仍具韌性。；半導體設備零組件需求則受 AI 相關資本支出帶動，呈現穩定成長。；口頭提及 1 至 4 月整體毛利率約 23%，第一季財報毛利率約 20% 多，4 月毛利率相對較高。。\n- 扣分或保留：航太供應鏈仍受波音、空巴及發動機交付節奏影響，實際拉貨與交機可能波動。；美國關稅、232 條款與相關政策仍有後續審查與執行不確定性。；半導體設備需求雖成長，但仍需觀察客戶資本支出節奏與終端需求變化。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
