          "detailMarkdown": "## 3034 聯詠 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（71 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 3、保守訊號 0。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 1Q26 營收 **231.45 億元**；毛利 **90.40 億元**；營業利益 **40.28 億元**；稅後淨利 **37.67 億元**。\n- 產品結構方面，簡報顯示 **SoC 102.40 億元**、**Driver IC 129.33 億元**；轉錄提到 SoC 佔比約 **44%**、Driver IC 約 **56%**。\n- 轉錄提及 1Q26 **SoC 產品線成長、Driver IC 下滑**；簡報數字顯示 SoC 季增 **26.51%**、Driver IC 季減 **12.27%**。\n- 截至 2026/3/31，現金及約當現金 **489.19 億元**，應收帳款淨額 **179.24 億元**，存貨 **108.51 億元**。\n- 管理層說明第一季存貨天數約 **72 天**，較前一季增加，主因部分材料漲價。\n\n### 展望與成長利基\n- 2Q26 合併營收預估 **275 億至 285 億元**，匯率假設 **1 美元兌 31.3 元台幣**。\n- 2Q26 毛利率預估 **38% 至 41%**，營業利益率預估 **16% 至 19%**。\n- 管理層表示，第二季三大產品線皆有望季增，其中 **SoC 成長幅度最大**。\n- 需求面上，**NB、平板、部分車用應用**需求較佳；**手機整體持平**，但 **LCD TDDI** 需求上升。\n- 下半年預期持續推出新產品，包括 **Edge AI 影像視覺、摺疊手機 OLED TDDI、OLED NB、Gaming Monitor** 等高階應用。\n\n### 產品、客戶與市場位置\n- 管理層指出，第一季營收回升主要受 **SoC 業務成長** 及部分產品組合優化帶動，抵銷手機需求走弱影響。\n- 第二季展望較第一季改善，主要受 **客戶提前拉貨、記憶體漲價、產品組合改善** 支撐。\n- 產品結構方面，簡報顯示 **SoC 102.40 億元**、**Driver IC 129.33 億元**；轉錄提到 SoC 佔比約 **44%**、Driver IC 約 **56%**。\n- 轉錄提及 1Q26 **SoC 產品線成長、Driver IC 下滑**；簡報數字顯示 SoC 季增 **26.51%**、Driver IC 季減 **12.27%**。\n- 管理層表示，第二季三大產品線皆有望季增，其中 **SoC 成長幅度最大**。\n- 下半年預期持續推出新產品，包括 **Edge AI 影像視覺、摺疊手機 OLED TDDI、OLED NB、Gaming Monitor** 等高階應用。\n\n### 風險與不確定性\n- 管理層提到 **記憶體供應緊缺與價格上漲**，對終端需求與成本皆有影響。\n- 第二季與下半年皆面臨 **KGD、金價、Wafer、Substrate、封測成本上揚** 的壓力。\n- 下半年不確定性來自 **地緣政治、中東局勢** 與消費性電子需求變化。\n- AI 需求帶動產能排擠效應，後段製程與封測資源可能偏緊，需持續與供應商協調。\n- 先進製程 ASIC 專案仍在開發，短期內 **未見營收貢獻**。\n- **需人工確認：** 轉錄提到「第一季毛利率超過指引上限，指引為 **36%~39%**」；簡報與英文稿未明列 1Q 指引，但呈現為**實際毛利率 39.06%**、且 Q2 指引為 **38%~41%**。\n- **需人工確認：** 轉錄中一度提到 Q2 或全年稅率指引時，出現「**2025 年全年所得稅率 16%~17%**」等字樣，前後語意混雜；可能原意為 **2026/2025 全年稅率維持 16%~17%**，建議核對原音。\n- **需人工確認：** 轉錄提到「**4 奈米 HPC**」與其他段落的「**10 奈米 HPC**」混用；以英文/中文轉錄多處顯示為 **4nm HPC POC demo system**，建議確認。\n\n### Q&A 與管理層口氣\n- 第一季稅後淨利 **37.67 億元**，EPS **6.19 元**；毛利率 **39.06%**，季增 **0.87 個百分點**。\n- 第二季展望較第一季改善，主要受 **客戶提前拉貨、記憶體漲價、產品組合改善** 支撐。\n- 2Q26 毛利率預估 **38% 至 41%**，營業利益率預估 **16% 至 19%**。\n- 管理層提到 **記憶體供應緊缺與價格上漲**，對終端需求與成本皆有影響。\n- 第二季與下半年皆面臨 **KGD、金價、Wafer、Substrate、封測成本上揚** 的壓力。\n- AI 需求帶動產能排擠效應，後段製程與封測資源可能偏緊，需持續與供應商協調。\n\n### 評分利基點\n- 加分主因：管理層指出，第一季營收回升主要受 **SoC 業務成長** 及部分產品組合優化帶動，抵銷手機需求走弱影響。；第二季展望較第一季改善，主要受 **客戶提前拉貨、記憶體漲價、產品組合改善** 支撐。；轉錄提及 1Q26 **SoC 產品線成長、Driver IC 下滑**；簡報數字顯示 SoC 季增 **26.51%**、Driver IC 季減 **12.27%**。。\n- 扣分或保留：管理層提到 **記憶體供應緊缺與價格上漲**，對終端需求與成本皆有影響。；第二季與下半年皆面臨 **KGD、金價、Wafer、Substrate、封測成本上揚** 的壓力。；下半年不確定性來自 **地緣政治、中東局勢** 與消費性電子需求變化。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
