          "detailMarkdown": "## 6526 達發 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（71 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 3、保守訊號 0。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 2026Q1 毛利率 **52.7%**，較去年同期增加 **1.0 個百分點**，較前一季減少 **0.9 個百分點**，主要受產品組合影響。\n- 營業費用約 **20.6 億元**，年增 **5.0%**、季增 **4.9%**；研發費用維持高檔。\n- 營業利益約 **8.2 億元**，年增 **10.7%**、季增 **71.1%**；淨利約 **7.5 億元**，年增 **5.1%**、季增 **40.0%**。\n- EPS 為 **4.47 元**，較去年同期 **4.36 元** 增加。\n- 截至 2026Q1，現金及約當現金約 **124.3 億元**；存貨淨額約 **27.2 億元**，存貨週轉天數由 **103 天** 降至 **93 天**。\n\n### 展望與成長利基\n- **光通訊**：管理層表示今年營收規模可望達去年 **3 倍以上**，Q2 續成長，未來幾年維持強勁成長曲線。\n- **以太網**：受低軌衛星客戶擴張、AI 資料中心 OOB 架構導入等帶動，全年呈現逐季攀升走勢。\n- **寬頻**：10G PON 滲透率提升、25G PON 持續送樣，有助於穩健成長；AI 資料中心帶外管理應用也在推進。\n- **無線邊緣 AI**：高階藍牙音訊與商務應用動能升溫，Q2 出貨可望明顯改善。\n- 全年來看，光通訊、以太網與低軌衛星合計營收比重，預期由去年的低個位數提升至 **高個位數**。\n\n### 產品、客戶與市場位置\n- 公司自本季起調整事業群與部分產品線名稱，以更貼近產品定位；說明聚焦於 **無線邊緣 AI** 與 **有線網通基礎建設**。\n- 會中多次強調 AI 資料中心、低軌衛星、光通訊為中期主要成長來源。\n- 2026Q1 毛利率 **52.7%**，較去年同期增加 **1.0 個百分點**，較前一季減少 **0.9 個百分點**，主要受產品組合影響。\n- **以太網**：受低軌衛星客戶擴張、AI 資料中心 OOB 架構導入等帶動，全年呈現逐季攀升走勢。\n- **寬頻**：10G PON 滲透率提升、25G PON 持續送樣，有助於穩健成長；AI 資料中心帶外管理應用也在推進。\n- **無線邊緣 AI**：高階藍牙音訊與商務應用動能升溫，Q2 出貨可望明顯改善。\n\n### 風險與不確定性\n- 供應鏈仍面臨 **AI 需求排擠產能**、晶圓與封測成本變動等壓力，但公司表示目前出貨未受影響。\n- 管理層提到部分寬頻客戶有 **提前拉貨** 與觀望並存情況，對下半年影響目前未擴大。\n- 匯率波動仍是風險來源；公司採取自然避險與反向部位調整，但台幣升值仍可能影響以台幣表達的獲利數字。\n- 簡報所列前瞻性內容受市場競爭、技術導入、客戶接受度、產能與經濟環境等因素影響。\n- LPO/LRO 等新型光通訊架構仍在觀察期，短期內管理層認為 **尚非主流應用**。\n- 需人工確認：轉錄中多處將 **「個百分點」** 與 **「%」** 混用；依簡報，營收/費用/獲利為年增或季增百分比，毛利率等為百分點變化。\n- 需人工確認：轉錄提到 **「有線通訊基礎事業群」**，簡報與其他段落多用 **「有線網通基礎建設事業群」**，應為同一事業群但命名需確認。\n- 需人工確認：轉錄中出現 **「九揚／久陽電子」** 等名稱，簡報僅以子公司合併數字呈現，子公司正式名稱需確認。\n\n### Q&A 與管理層口氣\n- 光通訊：100G 相關產品預計 **今年年中** 量產出貨；200G 研發團隊與 IP 已到位，藍圖與時程預計於下次法說再更新。\n- TIA：目前主要搭配 50G DSP 出貨；100G TIA 預期將與新一代 100G DSP 同步推出，長期目標為全面搭載。\n- 北美 CSP：寬頻 POE 與以太網 5G 晶片已成功切入北美大型 CSP／伺服器供應鏈，並已出貨。\n- 人力：截至 Q1，含久陽電子約 **1,540 人**；公司表示會依各產品線計畫審慎配置人力。\n- 集團合作：光通訊領域將與聯發科進行必要的合作開發；職能分工上，聯發科聚焦 scale-up，達發聚焦 scale-out 可插拔光收發模組晶片。\n\n### 評分利基點\n- 加分主因：營收成長主因來自 **有線網通基礎建設事業群** 出貨動能強勁，尤以光通訊、以太網較明顯。；管理層提到，**2026Q2** 營收動能可望延續，整體營收預期較去年同期與今年第一季皆成長。；會中多次強調 AI 資料中心、低軌衛星、光通訊為中期主要成長來源。。\n- 扣分或保留：供應鏈仍面臨 **AI 需求排擠產能**、晶圓與封測成本變動等壓力，但公司表示目前出貨未受影響。；管理層提到部分寬頻客戶有 **提前拉貨** 與觀望並存情況，對下半年影響目前未擴大。；匯率波動仍是風險來源；公司採取自然避險與反向部位調整，但台幣升值仍可能影響以台幣表達的獲利數字。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
