          "detailMarkdown": "## 4968 立積 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（52 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 2。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 2026Q1 營收 **9.30 億元**，QoQ **-2%**、YoY **+10%**；簡報與轉錄一致。\n- 2026Q1 毛利率 **33%**，較前一季 **-6ppt**；轉錄說明主因為 **Supply Chain 漲價**。\n- 2026Q1 營業利益 **1,994 萬元**，營益率 **2%**；EPS **0.58 元**。\n- 產品別營收：Wi-Fi 約 **8.25 億元**、其他約 **1.05 億元**；Wi-Fi 仍為主要營收來源。\n- 產品組合：Wi-Fi 產品營收占比約 **69%**，其中 FEM 比重提升；手機、車用與其他應用占比相對較小。\n\n### 展望與成長利基\n- Wi-Fi 7 出貨量持續成長，管理層表示 **今年 Wi-Fi 7 成長動能仍強**。\n- Wi-Fi 8 目前仍屬早期合作與開發階段，**2026 年營收貢獻有限**；較可能在 **2027 年下半年** 開始貢獻。\n- 車用產品線可見新案推進，尤其是 **FEM / 模組化** 需求；公司對下半年看法較上半年正向。\n- 管理層重申毛利率目標朝 **回到 30%** 邁進，並提及長期有機會往 **35%** 靠近。\n- 非 Wi-Fi 業務（如車用、手機、其他應用）被視為下半年有助於組合優化的來源。\n\n### 產品、客戶與市場位置\n- 2026Q1 營收年增、季減；管理層將 Q1 毛利率下滑歸因於 **供應鏈漲價與產品組合變化**。\n- 車用產品線持續導入新案，現階段出現 **FEM/module** 需求擴大。\n- 2026Q1 毛利率 **33%**，較前一季 **-6ppt**；轉錄說明主因為 **Supply Chain 漲價**。\n- 產品別營收：Wi-Fi 約 **8.25 億元**、其他約 **1.05 億元**；Wi-Fi 仍為主要營收來源。\n- 產品組合：Wi-Fi 產品營收占比約 **69%**，其中 FEM 比重提升；手機、車用與其他應用占比相對較小。\n- 車用產品線可見新案推進，尤其是 **FEM / 模組化** 需求；公司對下半年看法較上半年正向。\n\n### 風險與不確定性\n- Q1 毛利率受 **供應鏈成本上升** 影響，後續成本變動仍具不確定性。\n- Wi-Fi 7 / Wi-Fi 8、手機與車用案子的 **客戶導入時程** 及量產速度仍不確定。\n- 轉錄多次提到 **客戶成本分攤、運營商拉貨節奏、供應鏈價格** 等因素，可能影響後續出貨。\n- 車用、手機、衛星、機器人、無人機等題材多屬 **研發或洽談中**，商轉時點未明。\n- 公司聲明亦提及匯率、供需變化、競爭、法規與客戶流失等一般風險。\n- **需人工確認：Wi-Fi 7 營收占比**\n- 轉錄提及 2026Q1 Wi-Fi 7 約占 **56%**。\n- 簡報僅顯示 Wi-Fi 產品內部結構圖，未直接列出 56% 數字；另簡報可見 Wi-Fi 7 出貨成長但未明列占比。\n\n### Q&A 與管理層口氣\n- 市場詢問 **產品組合與毛利率走勢**：管理層表示將以 Wi-Fi 7、製程效率提升與非 Wi-Fi 業務改善毛利。\n- 市場詢問 **車用進度**：公司提到車用有較長認證與供貨週期，且有 **10 年供貨承諾** 特性。\n- 市場詢問 **Wi-Fi 7 滲透率與 carrier 拉貨**：管理層表示今年 Wi-Fi 7 adoption 已過半，且 7 的出貨已逐步超過 6。\n- 市場詢問 **手機 FEM / discrete、手錶案子**：手機 FEM 已出貨一段時間，手錶案子目前量仍小。\n- 市場詢問 **衛星、機器人、無人機**：多屬研究或初步接觸階段，尚未揭露具體商機。\n\n### 評分利基點\n- 加分主因：Wi-Fi 7 出貨動能持續，並與主晶片平台合作推進 **Wi-Fi 8** 開發。；車用產品線持續導入新案，現階段出現 **FEM/module** 需求擴大。；產品組合：Wi-Fi 產品營收占比約 **69%**，其中 FEM 比重提升；手機、車用與其他應用占比相對較小。。\n- 扣分或保留：Q1 毛利率受 **供應鏈成本上升** 影響，後續成本變動仍具不確定性。；Wi-Fi 7 / Wi-Fi 8、手機與車用案子的 **客戶導入時程** 及量產速度仍不確定。；轉錄多次提到 **客戶成本分攤、運營商拉貨節奏、供應鏈價格** 等因素，可能影響後續出貨。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
