          "detailMarkdown": "## 2308 台達電 詳細摘要\n\n### 判讀結論\n- 展望評價：正面看好（85 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 5、保守訊號 0。\n\n### 會議脈絡\n- 2026/04/30 台達電（2308）舉行 1Q 2026 法人說明會，簡報財務數字依 IFRS 編製，合併數字經 CPA 核閱。\n- 1Q 2026 營收 1,594 億元，年增 34%、季減 1%；毛利 590 億元，毛利率 37.0%，創高。\n- 管理階層指出，成長主軸來自 AI Data Center 相關需求，尤其是 Power Electronics 與 Infrastructure。\n- 會中多次提及 customer demand 成長快於供給準備，產能規劃偏向前瞻擴充。\n- 董事長強調，AI 相關產品組合比重提升，帶動整體獲利表現改善。\n\n### 展望與利基\n- 管理層表示，AI Data Center 需求仍是主要成長動能，且 hyperscaler CAPEX 仍維持高成長背景。\n- Power / Cooling 相關業務在 1Q 仍維持高占比，會中口頭提及 cooling system、power 的占比延續增長。\n- HVDC 部分，正負 400V 的出貨預期較早，800V 則預期較晚，口頭敘述以 2027 相關導入節奏為主。\n- Modular data center 被定位為下一波發展方向，較可能先對 co-location 客戶、後續再擴展到 enterprise 客戶。\n- 燃料電池（SOFC）今年以送樣、試運轉為主；量產與正式交貨節奏，管理層口頭指向明年。\n\n### 分數利基點\n- 管理層表示，AI Data Center 需求仍是主要成長動能，且 hyperscaler CAPEX 仍維持高成長背景。\n- HVDC 部分，正負 400V 的出貨預期較早，800V 則預期較晚，口頭敘述以 2027 相關導入節奏為主。\n- Modular data center 被定位為下一波發展方向，較可能先對 co-location 客戶、後續再擴展到 enterprise 客戶。\n- 燃料電池（SOFC）今年以送樣、試運轉為主；量產與正式交貨節奏，管理層口頭指向明年。\n\n### 需要保留的疑慮\n- Modular data center 被定位為下一波發展方向，較可能先對 co-location 客戶、後續再擴展到 enterprise 客戶。"
