          "detailMarkdown": "## 2409 友達 詳細摘要\n\n### 判讀結論\n- 展望評價：正面看好（71 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 3、保守訊號 0。\n\n### 會議脈絡\n- 2026 年第一季營收為 **690 億元**，季減約 1.6% 至 2%，公司表示三大營運支柱表現大致符合原先預期。\n- 第一季毛利率提升至 **11.9%**，主要受惠匯率、電視面板漲價與產品組合優化。\n- 公司同步揭露 **Mobility Solution** 與 **Vertical Solution** 的營收與營業利益率，作為後續分部追蹤基礎。\n- 管理層強調公司持續由顯示製造轉向以技術驅動的系統與解決方案供應商。\n- 2026 年第二季整體展望偏向分部別成長分化，Display 相對偏弱，Vertical 與 Mobility 相對較佳。\n\n### 展望與利基\n- 第二季 **Mobility Solution** 營收預期季增 **Low to Mid single digits**。\n- 第二季 **Vertical Solution** 營收預期季增 **High single digits**。\n- 第二季 **Display Solution** 營收預期較第一季 **略為減少**。\n- 全年折舊預估維持約 **280 億元**；全年資本支出目標維持 **不超過 200 億元**。\n- 北美客戶新訂單與墨西哥產能擴充將持續推動中長期量產能力。\n\n### 分數利基點\n- 北美客戶新訂單與墨西哥產能擴充將持續推動中長期量產能力。\n\n### 需要保留的疑慮\n- 目前摘要中未出現明顯負向或保守訊號，但仍需留意公司未量化揭露的部分。"
