          "detailMarkdown": "## 4743 合一 詳細摘要\n\n### 判讀結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 0、保守訊號 0。\n\n### 會議脈絡\n- 本次重點聚焦在 **ON101（簡報/口述亦見 OW101、Bonvadis®、Fespixon 等名稱）全球商化進度** 與 **新藥研發進展**。\n- 公司表示 ON101 已完成 **中國、美國、歐盟** 等主要市場的階段性准入，並以新藥與醫材雙軌推進全球布局。\n- 新藥管線以 **FB825、FB704A、SNS812、SNS851** 為主，分別涵蓋異位性皮膚炎、氣喘、新冠與減重領域。\n- 管理層強調 2026 年為「**法規准入走向商化推進**」的重要階段，並提及持續累積臨床數據、KOL 共識與真實世界資料。\n- ESG 部分，簡報提及公司連續四年入選 **S&P Global Sustainability Yearbook**。\n\n### 展望與利基\n- ON101 目標在 2026 年達成 **70 個國家/地區准入**；簡報稱截至目前已通過 **45 個國家/地區**。\n- 美國市場將同時推進 **保險給付、退伍軍人醫療體系、自費市場**，並以 CMS 支付框架與 KOL 共識作為基礎。\n- 歐洲市場採 **分國推進、雙軌商化**，先以南歐自費市場切入，再推進德、英、法等保險與政府標案市場。\n- 中國大陸市場將等待 **120 例上市後研究** 之解盲結果，並視結果評估是否申請擴充適應症。\n- SNS851 已啟動澳洲一期臨床，預計 **2026 年 Q4** 完成；FB825、FB704A 亦各有後續收案與解盲時程。\n\n### 分數利基點\n- 目前未看到足夠明確的正向展望訊號，因此分數較偏中性。\n\n### 需要保留的疑慮\n- 目前摘要中未出現明顯負向或保守訊號，但仍需留意公司未量化揭露的部分。"
