          "detailMarkdown": "## 6261 久元 詳細摘要\n\n### 判讀結論\n- 展望評價：中性觀望（52 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 2、保守訊號 2。\n\n### 會議脈絡\n- 久元電子於 **2026/04/29** 舉行線上法人說明會，主軸為營運概況、獲利情況與未來展望。\n- 公司成立於 **1991 年**，**2004 年上櫃**，資本額 **12.85 億元**，集團員工人數約 **1,000 人以上**。\n- 主要業務分為兩大類：**半導體／光電／RFID 代工服務** 與 **設備銷售**。\n- 語音轉錄提到公司近年營運動能來自自有設備銷售成長，半導體代工仍維持穩定規模。\n- 簡報與轉錄均強調公司目標為發展後段製程解決方案與設備品牌。\n- **未揭露**：本次簡報未提供完整逐季財務報表或更細部營運拆解。\n\n### 展望與利基\n- 轉錄提到公司將持續配合客戶需求，關注 **CPU 測試業務**、**AOI** 與 **矽光子** 等市場趨勢。\n- 公司表示將持續投入後段製程相關能力，包括代工、設備自製與技術維修。\n- 轉錄提及 2025 年有 **資本支出需求** 與 **建廠計畫**，可能影響現金運用配置。\n- 簡報中的經營願景為「立足台灣、放眼世界」的後段解決方案服務供應商與設備品牌商。\n- **未揭露**：未提供具體年度營收、毛利率或 EPS 指引。\n\n### 分數利基點\n- 轉錄提到公司將持續配合客戶需求，關注 **CPU 測試業務**、**AOI** 與 **矽光子** 等市場趨勢。\n- 轉錄提及 2025 年有 **資本支出需求** 與 **建廠計畫**，可能影響現金運用配置。\n\n### 需要保留的疑慮\n- 轉錄提及 2025 年有 **資本支出需求** 與 **建廠計畫**，可能影響現金運用配置。\n- **未揭露**：未提供具體年度營收、毛利率或 EPS 指引。\n- **未揭露**：本次簡報未提供完整逐季財務報表或更細部營運拆解。"
