          "detailMarkdown": "## 6548 長科* 詳細摘要\n\n### 判讀結論\n- 展望評價：正面看好（85 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 5、保守訊號 0。\n\n### 會議脈絡\n- 2026 年第一季營收 **36.72 億元**，QoQ **+4.8%**、YoY **+15%**，營運維持成長。\n- 管理層提到產品需求以 **QFN、EMC LED** 較強，**SO 系列**亦有增加趨勢，特別是電源管理相關應用。\n- 第二季展望維持正面，管理層表示 **訂單動能延續**，並預期部分客戶需求仍強。\n- 海外擴產持續推進，**馬來西亞與中國大陸**投資計畫皆已啟動。\n- 會中多次提到 **伺服器電源管理、800V HVDC、Power Control** 等需求帶動相關產品機會。\n\n### 展望與利基\n- 公司對 **2Q26 訂單動能**看法正面，並指出目前接單能見度仍佳。\n- 管理層提到 **3 月、4 月**拉貨動能強，並認為 2Q 表現可望維持向上。\n- **IC、Discrete、電源管理相關產品**需求較佳，尤其與資料中心、伺服器電源有關的應用。\n- **中國大陸山東威海新廠**：管理層說明為第三個生產基地，主要因大陸需求強、供應鏈完整且有現成廠房。\n- **馬來西亞新廠**：預估較晚貢獻，管理層提及時點約落在 **2027 年第三季**（需人工確認，與會中其他描述略有時間差）。\n\n### 分數利基點\n- 公司對 **2Q26 訂單動能**看法正面，並指出目前接單能見度仍佳。\n- **IC、Discrete、電源管理相關產品**需求較佳，尤其與資料中心、伺服器電源有關的應用。\n- **中國大陸山東威海新廠**：管理層說明為第三個生產基地，主要因大陸需求強、供應鏈完整且有現成廠房。\n- **馬來西亞新廠**：預估較晚貢獻，管理層提及時點約落在 **2027 年第三季**（需人工確認，與會中其他描述略有時間差）。\n\n### 需要保留的疑慮\n- 目前摘要中未出現明顯負向或保守訊號，但仍需留意公司未量化揭露的部分。"
