          "detailMarkdown": "## 6581 鋼聯 詳細摘要\n\n### 判讀結論\n- 展望評價：中性偏正面（58 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 2、保守訊號 1。\n\n### 會議脈絡\n- 公司定位為資源再生廠，核心業務為處理電弧爐集塵灰與含鋅廢棄物，並延伸至焚化飛灰、污染土壤等再利用。\n- 簡報與轉錄均強調「高溫旋轉窯」與「100%循環經濟、零廢棄物」模式，產品以粗氧化鋅與旋轉窯爐渣為主。\n- 2026Q1 營收與獲利年對年下滑，主要受處理量、銷售量變化與匯率等因素影響。\n- 展望面聚焦氧化鋅供不應求、環評變更後可增加收受量、龍井水洗廠預計 2027 年營運。\n- Q&A 聚焦於焚化飛灰成長性、加工費趨勢、鋼筋/電爐端原料量變化等。\n\n### 展望與利基\n- 氧化鋅業務方面，簡報稱 2026 年已完售且供不應求；環評變更通過後，有助提升含鋅資源物收受量與產量。\n- 加工費 2026 年由 US$80 調整至 US$85，簡報形容仍處低檔；轉錄亦提到加工費已「止跌」。\n- 龍井水洗廠主打氧化鋅水洗服務與產品高值化，預計 2027 年正式營運。\n- 焚化飛灰業務方面，簡報指出環評放寬收受量上限，並已取得 4 家大型焚化廠標案與 2 家 BOT 業者委託案。\n- 綠電建置持續推進，屋頂太陽能新增容量 3,831KW，預計 2026 年底前完成，屆時再生能源比例目標達 32%。\n\n### 分數利基點\n- 氧化鋅業務方面，簡報稱 2026 年已完售且供不應求；環評變更通過後，有助提升含鋅資源物收受量與產量。\n\n### 需要保留的疑慮\n- 2026Q1 營收與獲利年對年下滑，主要受處理量、銷售量變化與匯率等因素影響。"
